Text.text:
{= 'Foram identificadas '
                + ${dashboard>/falhasMovimentacao}
                + ' divergências entre a localização cadastrada no SAP e a localização detectada pela infraestrutura RFID. O indicador mede a confiabilidade operacional da solução e sua aderência às informações corporativas registradas no SAP.' }

{= 'O piloto atingiu '
                                            + ${dashboard>/coberturaValorGerado}
                                            + '% da meta de implantação prevista, correspondendo a '
                                            + ${dashboard>/instalados}
                                            + ' dos 50 rastreadores planejados para o escopo inicial da iniciativa.' }

{= 'A disponibilidade de monitoramento alcançou '
                                            + ${dashboard>/disponibilidadeMonitoramento}
                                            + '%, demonstrando capacidade consistente de acompanhamento de '
                                            + ${dashboard>/componentesDisponiveis}
                                            + ' dos '
                                            + ${dashboard>/totalComponentesValorGerado}
                                            + ' componentes elegíveis do piloto.' }

{= 'A infraestrutura de gateways instalados alcançou '
                                            + ${dashboard>/percentualGateway}
                                            + '% da implantação planejada, correspondendo a '
                                            + ${dashboard>/gateways}
                                            + ' dos 7 gateways previstos para o piloto.' }

{= 'A consistência das movimentações atingiu '
                                            + ${dashboard>/percentualConsistenciaMovimentacao}
                                            + '%, representando '
                                            + ${dashboard>/consistenciasMovimentacao}
                                            + ' dos '
                                            + ${dashboard>/online}
                                            + ' componentes monitorados com aderência entre a localização registrada e a posição identificada pela solução.' }

{= 'O Índice Geral de Efetividade atingiu '
                                            + ${dashboard>/indiceEfetividade}
                                            + '%, classificando o desempenho geral do piloto como '
                                            + ${dashboard>/classificacaoEfetividade}
                                            + '. Os resultados obtidos demonstram maturidade operacional suficiente para suportar a ampliação gradual da solução para novos ativos e áreas da operação.' }
